const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

module.exports = btc_nodes

async function btc_nodes(opts = {}, protocol, { onClose } = {}) {
  const { sdb } = await get(opts.sid)
  const { drive } = sdb
  const on = { style: inject, data: ondata, icons: onicons }
  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <section class="inspector-page">
      <header class="topbar"><button class="back-button" data-action="back" aria-label="Back">‹</button><div><p>Advanced inspector</p><h1>Nodes</h1></div><span class="readonly-badge">Read only</span></header>
      <div class="controls">
        <div class="segmented" role="tablist">
          <button class="active" data-service="lightning">Lightning</button><button data-service="bitcoin">Bitcoin</button>
        </div>
      </div>
      <div class="loading-state"><span class="loading-ring"></span><p>Reading node diagnostics…</p></div>
      <div class="error-state hidden"><span>!</span><strong>Node diagnostics unavailable</strong><p></p></div>
      <div class="loaded-state hidden">
        <div class="status-card"></div>
        <div class="content-tabs"><button class="active" data-tab="overview">Overview</button><button data-tab="raw">Raw JSON</button></div>
        <section class="overview-panel"></section>
        <section class="raw-panel hidden"><label>Dataset<select class="dataset-select"></select></label><pre class="json-output"></pre></section>
        <p class="captured-at"></p>
      </div>
    </section>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const sendUp = protocol ? protocol(receiveFromParent) : null
  let selectedService = 'lightning'
  let selectedTab = 'overview'
  let snapshot = null
  let loadTimer = null

  await sdb.watch(onbatch)
  shadow.addEventListener('click', handleClick)
  shadow.querySelector('.dataset-select').addEventListener('change', renderRaw)

  el.open = function () { load() }
  return el

  function handleClick(event) {
    const action = event.target.closest('[data-action]')
    if (action?.dataset.action === 'back' && onClose) onClose()
    const service = event.target.closest('[data-service]')
    if (service) {
      selectedService = service.dataset.service
      shadow.querySelectorAll('[data-service]').forEach(button => button.classList.toggle('active', button === service))
      render()
    }
    const tab = event.target.closest('[data-tab]')
    if (tab) {
      selectedTab = tab.dataset.tab
      shadow.querySelectorAll('[data-tab]').forEach(button => button.classList.toggle('active', button === tab))
      shadow.querySelector('.overview-panel').classList.toggle('hidden', selectedTab !== 'overview')
      shadow.querySelector('.raw-panel').classList.toggle('hidden', selectedTab !== 'raw')
      if (selectedTab === 'raw') renderRaw()
    }
  }

  function load() {
    if (loadTimer) window.clearTimeout(loadTimer)
    snapshot = null
    showState('loading')
    request({ type: 'get_diagnostics_nodes', data: {} })
    loadTimer = window.setTimeout(function () {
      if (snapshot) return
      shadow.querySelector('.error-state p').textContent = 'The diagnostics request timed out. Check that the Flamingo backend and node services are running.'
      showState('error')
    }, 8000)
  }

  function receiveFromParent(message) {
    if (message?.type !== 'diagnostics_nodes_loaded') return
    const response = message.data || {}
    if (response.status !== 'success' || !response.data) {
      shadow.querySelector('.error-state p').textContent = friendlyError(response.error)
      showState('error')
      return
    }
    if (loadTimer) window.clearTimeout(loadTimer)
    snapshot = response.data
    showState('loaded')
    render()
  }

  function render() {
    if (!snapshot) return
    renderStatus()
    renderOverview()
    renderDatasetOptions()
    renderRaw()
    const time = new Date(snapshot.captured_at)
    shadow.querySelector('.captured-at').textContent = `Snapshot captured ${Number.isNaN(time.getTime()) ? snapshot.captured_at : time.toLocaleString()}`
  }

  function renderStatus() {
    const source = snapshot[selectedService]
    const online = source?.status === 'online'
    const info = snapshot.lightning?.info?.data || {}
    const activeNode = snapshot.node_id || 'node4'
    const title = selectedService === 'lightning' ? (info.alias || nodeLabel(activeNode)) : 'Bitcoin Core'
    const subtitle = selectedService === 'lightning' ? shortId(info.id || activeNode) : (snapshot.bitcoin?.blockchain?.data?.chain || 'Bitcoin service')
    const card = shadow.querySelector('.status-card')
    card.className = `status-card ${online ? 'online' : 'offline'}`
    card.innerHTML = `<span class="status-mark">${online ? '✓' : '!'}</span><div><small>${selectedService === 'lightning' ? nodeLabel(activeNode) : 'Shared chain backend'}</small><strong></strong><p></p></div><span class="status-pill">${online ? 'Online' : 'Offline'}</span>`
    card.querySelector('strong').textContent = title
    card.querySelector('p').textContent = subtitle
  }

  function renderOverview() {
    const panel = shadow.querySelector('.overview-panel')
    const info = snapshot.lightning?.info?.data || {}
    const funds = snapshot.lightning?.funds?.data || {}
    const liquidity = snapshot.lightning?.liquidity?.data || {}
    const peers = snapshot.lightning?.peers?.data || []
    const channels = funds.channels || []
    const confirmedOutputs = (funds.outputs || []).filter(output => output.status === 'confirmed')
    const onchainMsat = confirmedOutputs.reduce((sum, output) => sum + msatValue(output.amount_msat), 0)
    const warnings = [info.warning_bitcoind_sync, info.warning_lightningd_sync].filter(Boolean)

    if (selectedService === 'lightning') {
      panel.innerHTML = `
        <div class="metric-grid">
          ${metric('Block height', formatNumber(info.blockheight))}${metric('Connected peers', formatNumber(peers.filter(peer => peer.connected !== false).length))}
          ${metric('Active channels', formatNumber(liquidity.active_channels || channels.filter(channel => channel.state === 'CHANNELD_NORMAL').length))}${metric('On-chain funds', `${formatSats(onchainMsat / 1000)} sats`)}
          ${metric('Can send', `${formatSats(liquidity.outbound_sats)} sats`)}${metric('Can receive', `${formatSats(liquidity.inbound_sats)} sats`)}
        </div>
        <article class="detail-card"><h2>Node information</h2>${row('Node ID', info.id || 'Unavailable', true)}${row('Network', info.network || 'Unavailable')}${row('Version', info.version || 'Unavailable')}${row('Address', addressText(info))}${row('Channel health', liquidity.health?.status || 'Unavailable')}</article>
        ${warnings.length ? `<article class="warning-card"><strong>Node warning</strong><p>${escapeHtml(warnings.join(' · '))}</p></article>` : ''}
      `
    } else {
      const chain = snapshot.bitcoin?.blockchain?.data || {}
      const network = snapshot.bitcoin?.network?.data || {}
      const mempool = snapshot.bitcoin?.mempool?.data || {}
      const uptime = snapshot.bitcoin?.uptime?.data
      const wallets = snapshot.bitcoin?.wallets?.data || []
      const balance = snapshot.bitcoin?.wallet_balance?.data || {}
      panel.innerHTML = `
        <div class="metric-grid">
          ${metric('Block height', formatNumber(chain.blocks))}${metric('Headers', formatNumber(chain.headers))}
          ${metric('Sync progress', formatPercent(chain.verificationprogress))}${metric('Connections', formatNumber(network.connections))}
          ${metric('Mempool', `${formatNumber(mempool.size)} txs`)}${metric('Wallet balance', `${formatBtc(balance.btc)} BTC`)}
        </div>
        <article class="detail-card"><h2>Bitcoin service</h2>${row('Chain', chain.chain || 'Unavailable')}${row('Version', network.subversion || network.version || 'Unavailable')}${row('Loaded wallets', Array.isArray(wallets) && wallets.length ? wallets.join(', ') : 'None reported')}${row('Relay fee', network.relayfee !== undefined ? `${network.relayfee} BTC/kB` : 'Unavailable')}${row('Uptime', formatDuration(uptime))}${row('Warnings', network.warnings || chain.warnings || 'None')}</article>
      `
    }
  }

  function renderDatasetOptions() {
    const select = shadow.querySelector('.dataset-select')
    const current = select.value
    const options = selectedService === 'lightning'
      ? [['combined', 'Combined snapshot'], ['info', 'getinfo'], ['funds', 'listfunds'], ['liquidity', 'Liquidity report'], ['peers', 'listpeers']]
      : [['combined', 'Combined snapshot'], ['blockchain', 'Blockchain info'], ['network', 'Network info'], ['mempool', 'Mempool info'], ['uptime', 'Uptime'], ['wallets', 'Loaded wallets'], ['wallet_info', 'Wallet info'], ['wallet_balance', 'Wallet balance']]
    select.innerHTML = options.map(([value, label]) => `<option value="${value}">${label}</option>`).join('')
    if (options.some(option => option[0] === current)) select.value = current
  }

  function renderRaw() {
    if (!snapshot) return
    const key = shadow.querySelector('.dataset-select').value || 'combined'
    const source = snapshot[selectedService]
    const value = key === 'combined' ? source : source?.[key]
    shadow.querySelector('.json-output').textContent = JSON.stringify(value ?? null, null, 2)
  }

  function showState(state) {
    shadow.querySelector('.loading-state').classList.toggle('hidden', state !== 'loading')
    shadow.querySelector('.error-state').classList.toggle('hidden', state !== 'error')
    shadow.querySelector('.loaded-state').classList.toggle('hidden', state !== 'loaded')
  }
  function request(message) { if (typeof sendUp === 'function') sendUp({ from: 'btc_nodes', ...message }) }
  function nodeLabel(id) { return ({ node4: 'Node 4 · Wallet', node6: 'Node 6 · Test node' })[id] || id }
  function shortId(value) { return value.length > 22 ? `${value.slice(0, 12)}…${value.slice(-8)}` : value }
  function msatValue(value) { return typeof value === 'object' ? Number(value.msat || 0) : Number(value || 0) }
  function formatNumber(value) { return Number.isFinite(Number(value)) ? Number(value).toLocaleString() : 'Unavailable' }
  function formatSats(value) { return Number.isFinite(Number(value)) ? Math.floor(Number(value)).toLocaleString() : '0' }
  function formatBtc(value) { return Number.isFinite(Number(value)) ? Number(value).toFixed(8) : '0.00000000' }
  function formatPercent(value) { return Number.isFinite(Number(value)) ? `${(Number(value) * 100).toFixed(2)}%` : 'Unavailable' }
  function formatDuration(value) { return Number.isFinite(Number(value)) ? `${Math.floor(Number(value) / 3600)}h` : 'Unavailable' }
  function addressText(info) { const address = (info.address || info.binding || [])[0]; return address ? `${address.address || ''}:${address.port || ''}` : 'Not announced' }
  function metric(label, value) { return `<div class="metric"><small>${label}</small><strong>${escapeHtml(String(value))}</strong></div>` }
  function row(label, value, mono) { return `<div class="detail-row"><span>${label}</span><strong class="${mono ? 'mono' : ''}" title="${escapeHtml(String(value))}">${escapeHtml(String(value))}</strong></div>` }
  function friendlyError(error) { const text = String(error || 'The backend did not return node information.'); return text.includes('ECONNREFUSED') ? 'The node service is not reachable. Check that the Flamingo backend is running.' : text }
  function escapeHtml(value) { return value.replace(/[&<>"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[char]) }
  async function onbatch(batch) { for (const { type, paths } of batch) { const data = await Promise.all(paths.map(path => drive.get(path).then(file => file.raw))); await (on[type] || fail)(data, type) } }
  function inject(data) { style.textContent = data[0] }
  function ondata() {}
  function onicons() {}
  function fail(data, type) { throw new Error('invalid message', { cause: { data, type } }) }
}

function fallback_module() {
  return { api: fallback_instance }
  function fallback_instance(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}
    return { drive: { 'icons/': {}, 'style/': { 'style.css': { '$ref': 'btc_nodes.css' } }, 'data/': { 'opts.json': { raw: opts || {} } } } }
  }
}
